(() => {
  const cards=[...document.querySelectorAll('.task-board[data-column-id]')];
  const out = cards.map(c=>({col:c.getAttribute('data-column-id'), title:(c.querySelector('.task-board-header .task-board-title')||{}).textContent}));
  const all=[...document.querySelectorAll('.task-board-title a')].map(a=>({t:a.textContent.trim(), href:a.getAttribute('href')}));
  const card=document.querySelector('a[href*="task_id=4"]').closest('.task-board');
  const menu = card.querySelector('.dropdown');
  return {cols:out, all, menuHTML: menu? menu.outerHTML : null, cardHTML: card.outerHTML.slice(0,3000)};
})()

(() => {
  const tds=[...document.querySelectorAll('td, th')].filter(e=>e.hasAttribute('data-column-id'));
  const info = tds.map(t=>({tag:t.tagName, cid:t.getAttribute('data-column-id'), cls:t.className, childs:[...t.children].map(c=>c.tagName+'.'+c.className)}));
  const table = document.querySelector('#board') || document.querySelector('table');
  return {info, tableTag: table? table.outerHTML.slice(0,600):null, sortables: [...document.querySelectorAll('[class*=sortable], .task-board-list')].map(e=>e.tagName+'.'+e.className)};
})()

(() => {
  const ths=[...document.querySelectorAll('#board th.board-column-header')];
  const cols = ths.map(th=>{
    const tds=[...document.querySelectorAll('#board tr')][1];
    return th.getAttribute('data-column-id');
  });
  // map column id -> titles via task lists
  const lists=[...document.querySelectorAll('#board .board-task-list')].filter(l=>l.classList.contains('board-column-expanded'));
  const res={};
  [...document.querySelectorAll('#board .task-board')].forEach(c=>{
    res[c.getAttribute('data-task-id')] = {title:c.querySelector('.task-board-title').textContent.trim(), column:c.closest('td')?.className+'|'+(c.closest('td')?.cellIndex)};
  });
  const heads = ths.map(t=>({cid:t.getAttribute('data-column-id'), name:t.querySelector('.board-column-expanded-header')?.innerText.replace(/\s+/g,' ').trim().slice(0,80)}));
  return {heads, res};
})()
